WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_trv_m_multi'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '多次相遇', 'kp-trv-m-multi', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "多次相遇"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心结论：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "第 N 次相遇，两人共同走过的总路程是单程的 (2N - 1) 倍。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "两人相向而行，到了端点后立刻折返，在路上来回穿梭，发生第二次、第三次相遇。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心推论（画图可证）"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "第 1 次相遇：两人共走完 1 个单程。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "第 2 次相遇：从第一次相遇到第二次相遇，两人又合走完了 2 个单程。所以总共走完 3 个单程。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "第 3 次相遇：总共走完 5 个单程。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "第 N 次相遇：总共走完 2N - 1 个单程。"}]}]}]}, {"type": "katexBlock", "attrs": {"content": "(2N - 1) \\times S_{单程} = (V_A + V_B) \\times T_{相遇}"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[识别是第几次相遇] --> B[算出系数 2N-1]\nB --> C[总行程 = (2N-1) × 单程距离]\nC --> D[套用相遇公式: 总行程 = (Va+Vb) × T]\nD --> E[求出总时间 T, 或利用 T 求出某人走的绝对距离]"}}]}$$ AS jsonb), NULL, '多次相遇的核心考点与实战推导。', category_node.id, CAST('["数量关系", "行程问题", "多次相遇"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_trv_m_multi", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
